// run
package main

import (
	"fmt"
	"runtime"
	"sort"
	"time"
)

// The struct carries a pointer field so it is a normal heap object rather
// than one batched by the tiny allocator, whose blocks are only freed when
// every tenant dies.
type resource struct {
	id   int
	name string
}

var fin = make(chan int, 4)

func mkfin(id int) {
	r := &resource{id, "r"}
	runtime.SetFinalizer(r, func(x *resource) { fin <- x.id })
}

// The cleanup runs on its own goroutine, so the result is published through a
// channel rather than a shared slice.
var cleaned = make(chan int, 16)

func alloc(id int) {
	r := &resource{id, "r"}
	runtime.AddCleanup(r, func(n int) { cleaned <- n }, id)
}

// drain collects up to n cleanup results, forcing collections in between.
func drain(n int) []int {
	var got []int
	for i := 0; i < 400 && len(got) < n; i++ {
		runtime.GC()
		time.Sleep(time.Millisecond)
		for {
			select {
			case v := <-cleaned:
				got = append(got, v)
				continue
			default:
			}
			break
		}
	}
	sort.Ints(got)
	return got
}

func main() {
	for i := 0; i < 6; i++ {
		alloc(i)
	}
	got := drain(6)
	fmt.Println("every cleanup ran:", len(got) == 6, got)

	kept := &resource{99, "r"}
	runtime.AddCleanup(kept, func(n int) { fmt.Println("must not run", n) }, 99)
	runtime.GC()
	time.Sleep(2 * time.Millisecond)
	runtime.GC()
	fmt.Println("kept alive:", kept.id)

	stopped := &resource{7, "r"}
	h := runtime.AddCleanup(stopped, func(n int) { fmt.Println("stopped cleanup ran") }, 7)
	h.Stop()
	runtime.KeepAlive(stopped)

	func() {
		defer func() { fmt.Println("nil pointer rejected:", recover() != nil) }()
		var np *resource
		runtime.AddCleanup(np, func(n int) {}, 1)
	}()
	// SetFinalizer still works and is the older mechanism: it is passed the
	// object itself, so it can resurrect it, and only one may be attached.
	mkfin(1)
	mkfin(2)
	seen := 0
	for i := 0; i < 400 && seen < 2; i++ {
		runtime.GC()
		time.Sleep(time.Millisecond)
		for {
			select {
			case <-fin:
				seen++
				continue
			default:
			}
			break
		}
	}
	fmt.Println("finalizers ran:", seen)
	// `kept` is still reachable here, so its cleanup must never have run
	runtime.KeepAlive(kept)
	fmt.Println("done", kept.id)
}

