// run
package main

import (
	"bytes"
	"fmt"
	"slices"
	"strings"
)

func main() {
	// the Go 1.24 iterator forms of strings' splitting functions
	text := "alpha\nbeta\ngamma\n"
	fmt.Println(slices.Collect(strings.Lines(text)))
	fmt.Println(slices.Collect(strings.Lines("no trailing newline")))

	csv := "a,b,,c"
	fmt.Println(slices.Collect(strings.SplitSeq(csv, ",")))
	fmt.Println(slices.Collect(strings.SplitAfterSeq(csv, ",")))
	fmt.Println(slices.Collect(strings.FieldsSeq("  one   two three ")))
	fmt.Println(slices.Collect(strings.FieldsFuncSeq("a1b2c", func(r rune) bool {
		return r >= '0' && r <= '9'
	})))

	// early exit must stop the iteration
	var first []string
	for s := range strings.SplitSeq("p,q,r,s", ",") {
		first = append(first, s)
		if len(first) == 2 {
			break
		}
	}
	fmt.Println(first)

	// bytes has the same additions
	fmt.Println(len(slices.Collect(bytes.Lines([]byte("x\ny\n")))))
	for line := range bytes.Lines([]byte("k\nv\n")) {
		fmt.Printf("%q ", string(line))
	}
	fmt.Println()
}

