package main

import (
	"fmt"
	"sort"
	"sync"
	"sync/atomic"
)

// WaitGroup.Go was added in Go 1.25: it increments the counter, runs f in a
// new goroutine, and decrements when f returns -- including when f panics.
func main() {
	var wg sync.WaitGroup
	var mu sync.Mutex
	var got []int
	for i := 1; i <= 8; i++ {
		n := i
		wg.Go(func() {
			mu.Lock()
			got = append(got, n*n)
			mu.Unlock()
		})
	}
	wg.Wait()
	sort.Ints(got)
	fmt.Println(got)

	var counter atomic.Int64
	var wg2 sync.WaitGroup
	for i := 0; i < 50; i++ {
		wg2.Go(func() { counter.Add(1) })
	}
	wg2.Wait()
	fmt.Println("counter:", counter.Load())

	// the counter is released even when the function panics
	var wg3 sync.WaitGroup
	wg3.Go(func() {
		defer func() { fmt.Println("recovered:", recover()) }()
		panic("boom")
	})
	wg3.Wait()
	fmt.Println("wait returned after panic")

	// Wait on an empty group returns immediately
	var wg4 sync.WaitGroup
	wg4.Wait()
	fmt.Println("empty group ok")
}

