package main

import (
	"fmt"
	"sort"
)

type Number interface{ ~int | ~int64 | ~float64 }

type MyInt int

func Sum[T Number](xs []T) T {
	var total T
	for _, x := range xs {
		total += x
	}
	return total
}

func MapSlice[T, U any](xs []T, f func(T) U) []U {
	out := make([]U, 0, len(xs))
	for _, x := range xs {
		out = append(out, f(x))
	}
	return out
}

func Keys[K comparable, V any](m map[K]V) []K {
	out := make([]K, 0, len(m))
	for k := range m {
		out = append(out, k)
	}
	return out
}

type Stack[T any] struct{ items []T }

func (s *Stack[T]) Push(v T)     { s.items = append(s.items, v) }
func (s *Stack[T]) Len() int     { return len(s.items) }
func (s *Stack[T]) Pop() (T, bool) {
	var zero T
	if len(s.items) == 0 {
		return zero, false
	}
	v := s.items[len(s.items)-1]
	s.items = s.items[:len(s.items)-1]
	return v, true
}

type Pair[K comparable, V comparable] struct {
	Key K
	Val V
}

func (p Pair[K, V]) Swap() Pair[V, K] { return Pair[V, K]{p.Val, p.Key} }

func Max[T interface{ ~int | ~string }](a, b T) T {
	if a > b {
		return a
	}
	return b
}

func main() {
	fmt.Println(Sum([]int{1, 2, 3}), Sum([]float64{1.5, 2.5}), Sum([]MyInt{4, 5}))
	fmt.Println(Sum[int64]([]int64{7, 8}))
	fmt.Println(MapSlice([]int{1, 2, 3}, func(i int) string { return fmt.Sprint(i * 2) }))
	ks := Keys(map[string]int{"b": 2, "a": 1})
	sort.Strings(ks)
	fmt.Println(ks)

	var s Stack[string]
	s.Push("a")
	s.Push("b")
	v, ok := s.Pop()
	fmt.Println(v, ok, s.Len())
	var empty Stack[int]
	iv, iok := empty.Pop()
	fmt.Println(iv, iok)

	p := Pair[string, int]{"x", 1}
	fmt.Println(p, p.Swap(), p.Key, p.Val)
	fmt.Printf("%T %T\n", p, p.Swap())
	fmt.Println(Max(3, 9), Max("abc", "abd"))

	var anyv any = 42
	fmt.Println(anyv)
}

