package m

// Reverse reverses a string by runes.
func Reverse(s string) string {
	r := []rune(s)
	for i, j := 0, len(r)-1; i < j; i, j = i+1, j-1 {
		r[i], r[j] = r[j], r[i]
	}
	return string(r)
}

// Clip returns v clamped into [lo, hi].
func Clip(v, lo, hi int) int {
	if v < lo {
		return lo
	}
	if v > hi {
		return hi
	}
	return v
}

package m

import "testing"

func TestReverseSmall(t *testing.T) {
	if Reverse("ab") != "ba" {
		t.Fatal("bad reverse")
	}
}

// Without -fuzz, `go test` runs a fuzz target against its seed corpus only,
// once per f.Add entry, as a subtest named seed#N.
func FuzzReverse(f *testing.F) {
	f.Add("abc")
	f.Add("")
	f.Add("Hello, 世界")
	f.Fuzz(func(t *testing.T, s string) {
		t.Logf("seed %q", s)
		if got := Reverse(Reverse(s)); got != s {
			t.Errorf("round trip: got %q want %q", got, s)
		}
	})
}

func FuzzClip(f *testing.F) {
	f.Add(5, 0, 10)
	f.Add(-4, -1, 1)
	f.Fuzz(func(t *testing.T, v, lo, hi int) {
		got := Clip(v, lo, hi)
		if got < lo || got > hi {
			t.Errorf("Clip(%d,%d,%d) = %d out of range", v, lo, hi, got)
		}
		t.Logf("clip %d -> %d", v, got)
	})
}

