func main() {
	// slices.Concat (Go 1.22)
	a := []int{1, 2}
	b := []int{3}
	var empty []int
	got := slices.Concat(a, empty, b, nil)
	fmt.Println(got, len(got), cap(got) >= 3)
	fmt.Println(slices.Concat(empty, empty) == nil)
	a[0] = 99
	fmt.Println(got[0])

	// slices.Repeat (Go 1.23)
	fmt.Println(slices.Repeat([]string{"ab", "cd"}, 3))
	fmt.Println(slices.Repeat([]int{1}, 0), len(slices.Repeat([]int{1}, 0)))

	// the 1.22 clipping and deletion rules
	s := []int{1, 2, 3, 4, 5}
	fmt.Println(slices.Delete(slices.Clone(s), 1, 3))
	fmt.Println(slices.Insert(slices.Clone(s), 5, 6, 7))
	fmt.Println(slices.Replace(slices.Clone(s), 1, 3, 9))
	fmt.Println(slices.Clip(slices.Clone(s)[:2]))
	fmt.Println(slices.Grow(slices.Clone(s), 10)[:len(s)])
	fmt.Println(slices.CompactFunc([]string{"a", "A", "b"},
		func(x, y string) bool { return len(x) == len(y) && (x == y || x[0]|32 == y[0]|32) }))
}

