func Count(n int) iter.Seq[int] {
	return func(yield func(int) bool) {
		for i := 0; i < n; i++ {
			if !yield(i) {
				return
			}
		}
	}
}

func Enumerate[T any](xs []T) iter.Seq2[int, T] {
	return func(yield func(int, T) bool) {
		for i, v := range xs {
			if !yield(i, v) {
				return
			}
		}
	}
}

func sumTo(n int) int {
	total := 0
	for i := range n {
		total += i
	}
	return total
}

func firstEven(seq iter.Seq[int]) (int, bool) {
	for v := range seq {
		if v%2 == 0 && v > 0 {
			return v, true
		}
	}
	return 0, false
}

func main() {
	fmt.Println(sumTo(5), sumTo(0), sumTo(1))
	var seen []int
	for v := range Count(5) {
